save(108,dict(paragraphs=["Lopamudra Mishra’s English poems in Kabita Live explore the ways affection changes a person’s sense of self. In ‘I left behind’, familiar songs, books and dance steps give way to a life reshaped through companionship. The sky and stars remain the same while the speaker describes becoming someone new.","‘I woke up thinking about you’ makes a relationship audible through melody, rhythm and remembered words. A different energy animates ‘I am born different’: woodland, wind and imagined wings accompany a speaker seeking room beyond expectations. Together, these poems move between intimacy and the desire to preserve an individual voice."],sources=[],status='source_limited_local_draft',identity_match='Local contribution IDs secure the three poem bylines. Captured biography is empty; external English-poet biography is plausible but not yet bridged by a matching text or other local biographical detail.',poems_read=[dict(id=681,title='I woke up thinking about you',basis='Full text read: remembered melody, lyrical relationship, face in waves and words beneath words.'),dict(id=473,title='I am born different',basis='Full text read: wilderness, verse as refuge, wings, running and repeated affirmation of difference.'),dict(id=75,title='I left behind',basis='Full text read: songs/books/dance and changed identity in companionship under unchanged stars.')],limitations=['External sources describe a Bhubaneswar English poet and other namesakes; education, books, film work and awards not imported without identity bridge.','Azahar 131 has the same title as poem 681 but a different poem; not treated as an exact-text match.','No medical or disability inference drawn from poem 473.'],research_leads=[dict(url='https://positivevibes.today/article/newsview/742',finding='Opened literary journal: English poet, Bhubaneswar, six books and education; plausible candidate, not sufficient to attach biography to empty local record.'),dict(url='https://ourpoetryarchive.blogspot.com/2018/10/lopamudra-mishra.html?hl=hi_IN',finding='Indexed biography gives Puri/Bhubaneswar and three books; retained as candidate only.'),dict(url='https://www.lechasseurabstrait.com/revue/IMG/pdf/revista_131.pdf',finding='Indexed poem I WOKE UP THINKING ABOUT YOU starts with steel/stones and differs from local melody/relationship text; no replacement or merge.')],next_action='Author/editor confirm identity and bibliography; then integrate supported external biography.'))
